with w as(select*from public.works where open_library_id in('OL24343547W','OL42430111W','OL45586866W','OL28429W','OL37232624W','OL33675515W','OL45094754W','OL24178205W','OL42143816W','OL42542598W','OL17546674W','OL15026613W','OL19754749W','OL36090166W','OL16810944W','OL19922194W','OL28803485W','OL76835W','OL5842018W','OL26004554W','OL20861787W','OL554680W')) select jsonb_build_object('checked_at',clock_timestamp(),'project','hlvujbrmfdlrfxdjwsmb','works',(select jsonb_agg(to_jsonb(w)order by id)from w),'editions',(select jsonb_agg(to_jsonb(e)order by id)from public.editions e where work_id in(select id from w)),'authors',(select jsonb_agg(to_jsonb(a)order by id)from public.authors a where id in(select author_id from w)))as readback;